import { HttpClient } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { Owner } from '../models/owner.model';
import { Observable } from 'rxjs';
import { environment } from '../../../environments/environment';


@Injectable({
  providedIn: 'root'
})
export class OwnerService {

  apiUrl: string = environment.apiUrl + '/owners';

  constructor(private http: HttpClient) { }

  getOwnerById(idOwner: string): Observable<Owner> {
    return this.http.get<Owner>(`${this.apiUrl}/${idOwner}`);
  }

  getAllOwners(): Observable<Owner[]> {
    return this.http.get<Owner[]>(`${this.apiUrl}`);
  }

  getOwnerByToken(): Observable<Owner> {
    return this.http.get<Owner>(`${this.apiUrl}/getOwnerByToken`);
  }

}
